def cache_sim(capacity, ttl, ops):
    from collections import OrderedDict

    cache = OrderedDict()  # key -> [value, write_time]
    results = []

    def is_expired(key, t):
        return t >= cache[key][1] + ttl

    for op in ops:
        kind = op[0]
        t = op[1]
        if kind == 'put':
            key = op[2]
            value = op[3]
            if key in cache:
                if is_expired(key, t):
                    del cache[key]
            if key in cache:
                cache[key][0] = value
                cache[key][1] = t
                cache.move_to_end(key)
            else:
                if len(cache) >= capacity:
                    # evict LRU, but first check for expired entries to remove
                    # standard LRU eviction: remove least recently used
                    cache.popitem(last=False)
                cache[key] = [value, t]
                cache.move_to_end(key)
        elif kind == 'get':
            key = op[2]
            if key in cache and not is_expired(key, t):
                results.append(cache[key][0])
                cache.move_to_end(key)
            else:
                if key in cache:
                    del cache[key]
                results.append(-1)
    return results

